//#region src/lib/bill-entry.ts
/**
* Bills open only from the Tables screen: a table's bill, a running counter
* bill, or a new counter order. These are the orders that have no table.
*/
var COUNTER_TYPES = [
	{
		v: "takeaway",
		l: "Takeaway"
	},
	{
		v: "delivery",
		l: "Delivery"
	},
	{
		v: "swiggy",
		l: "Swiggy"
	},
	{
		v: "zomato",
		l: "Zomato"
	}
];
function isCounterType(value) {
	return COUNTER_TYPES.some((t) => t.v === value);
}
//#endregion
export { isCounterType as n, COUNTER_TYPES as t };
